PROGRAM="\nimport hashlib,json,pathlib,subprocess,sys,urllib.request\nbody=json.load(sys.stdin);base=pathlib.Path('/opt/lya-connect');stage=base/'updates/mobile-conversation-20261010'\nassert not stage.exists();stage.mkdir(mode=0o755)\np=stage/'mobile_tts.py';p.write_text(body['source']);p.chmod(0o644)\nvenv=base/'tts-venv'\nassert not venv.exists()\nsubprocess.run(['/usr/bin/python3','-m','venv',str(venv)],check=True,capture_output=True,timeout=40)\nsubprocess.run([str(venv/'bin/python'),'-m','pip','install','--disable-pip-version-check','--index-url','https://pypi.org/simple','piper-tts==1.8.0'],check=True,capture_output=True,timeout=120)\nfor p in venv.rglob('*'):\n if not p.is_symlink():p.chmod(0o755 if p.is_dir() or p.parent==venv/'bin' else 0o644)\nmodels=base/'models';models.mkdir(mode=0o755,exist_ok=True)\nfor name,digest in body['models'].items():\n assert name in ('en_US-amy-medium.onnx','en_US-amy-medium.onnx.json')\n p=models/name;assert not p.exists()\n url='https://huggingface.co/rhasspy/piper-voices/resolve/main/en/en_US/amy/medium/'+name\n with urllib.request.urlopen(url,timeout=25) as r, p.open('xb') as f:\n  while True:\n   chunk=r.read(1024*1024)\n   if not chunk:break\n   f.write(chunk)\n assert hashlib.sha256(p.read_bytes()).hexdigest()==digest;p.chmod(0o644)\nprint(json.dumps(dict(staged=True,installed_piper='1.8.0',public_model_matches_desktop=True,service_restarted=False,provider_call=False)))\n"
